"""Private Redis7.2 TCP peers, real cluster slots and migration; no external peers."""
import contextlib,socket,secrets,time
from redis_native import NativeRedis


def free_port():
    for _ in range(200):
        port=20000+secrets.randbelow(19000)
        try:
            with socket.socket() as client,socket.socket() as bus:
                client.bind(('127.0.0.1',port));bus.bind(('127.0.0.1',port+10000))
            return port
        except OSError:pass
    raise RuntimeError('NATIVE_ENVIRONMENT_ERROR: private TCP ports unavailable')


class TCPRedis(NativeRedis):
    def __init__(self,cluster=False):self.cluster=cluster;self.port=free_port();self.address='127.0.0.1:'+str(self.port)
    def start(self):
        if not getattr(self,'configured',False):
            with self.config.open('a',encoding='utf8') as stream:
                stream.write('\nport '+str(self.port)+'\nbind 127.0.0.1\nrepl-diskless-sync-delay 0\n')
                if self.cluster:
                    stream.write('cluster-enabled yes\ncluster-config-file cluster.conf\ncluster-node-timeout 1000\ncluster-announce-ip 127.0.0.1\ncluster-announce-port '+str(self.port)+'\ncluster-announce-bus-port '+str(self.port+10000)+'\n')
            self.configured=True
        super().start()


class Cluster:
    def __enter__(self):
        self.stack=contextlib.ExitStack()
        try:
            self.used_slots=set()
            self.source=self.stack.enter_context(TCPRedis(cluster=True))
            self.target=self.stack.enter_context(TCPRedis(cluster=True))
            self.source_id=self.source.command('CLUSTER','MYID');self.target_id=self.target.command('CLUSTER','MYID')
            self.source.command('CLUSTER','ADDSLOTSRANGE',0,8191)
            self.target.command('CLUSTER','ADDSLOTSRANGE',8192,16383)
            self.source.command('CLUSTER','MEET','127.0.0.1',self.target.port)
            deadline=time.monotonic()+8
            while time.monotonic()<deadline:
                if all('cluster_state:ok' in server.command('CLUSTER','INFO') and server.command('CLUSTER','NODES').count('\n')==2 for server in [self.source,self.target]):
                    print('NATIVE_CLUSTER_READY:2-private-masters',flush=True);return self
                time.sleep(.02)
            raise RuntimeError('NATIVE_ENVIRONMENT_ERROR: private cluster did not converge')
        except BaseException:self.stack.close();raise
    def __exit__(self,*args):self.stack.close()
    def tag(self):
        for _ in range(1000):
            tag='of_'+secrets.token_hex(8);slot=self.source.command('CLUSTER','KEYSLOT','{'+tag+'}:x')
            if slot<8192 and slot not in self.used_slots:
                self.used_slots.add(slot);return tag,slot
        raise RuntimeError('NATIVE_ENVIRONMENT_ERROR: could not select source slot')
    def begin(self,slot):
        self.target.command('CLUSTER','SETSLOT',slot,'IMPORTING',self.source_id)
        self.source.command('CLUSTER','SETSLOT',slot,'MIGRATING',self.target_id)
